//! Read-only smoke check. Never links, reviews, comments or changes a PR.
use omarchy_t3_client::*;use serde_json::json;
fn main(){for e in environments().unwrap_or_default(){let result=write::execute(&json!({"op":"pull-requests","environment":e.id,"action":"list","state":"open","involvement":"authored"}));match result{Ok(v)=>{println!("{}",json!({"environment":e.id,"entries":v["entries"].as_array().map(Vec::len),"projectErrors":v["errors"].as_array().map(Vec::len),"truncated":v["truncated"]}));if let Some(r)=v["entries"].as_array().and_then(|r|r.first()){for action in ["detail","checks","diff"]{let r=write::execute(&json!({"op":"pull-requests","environment":e.id,"action":action,"reference":r}));println!("{}",json!({"environment":e.id,"action":action,"ok":r.is_ok(),"error":r.err()}));}}},Err(err)=>println!("{}",json!({"environment":e.id,"error":err}))}}}
